// Check verification status
function checkVerificationStatus() {
    const token = getAccessToken();
    if (!token) return;

    /*
    // Check phone verification status
    ['mobile', 'phone'].forEach(fieldType => {
        const currentPhone = document.getElementById(fieldType)?.value || '';
        fetch('/cif/check_verification_status', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
            },
            body: new URLSearchParams({
                'field_type': fieldType,
                'token': token,
                'current_phone': currentPhone
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.success && data.verified) {
                // Hide verify button and OTP section
                const verifyBtn = document.getElementById('btn_verify_' + fieldType);
                if (verifyBtn) {
                    verifyBtn.style.display = 'none';
                }
                const otpSectionEl = document.getElementById(fieldType + '_otp_section');
                if (otpSectionEl) {
                    otpSectionEl.style.display = 'none';
                }
                // Show verified status
                const verifiedEl = document.getElementById(fieldType + '_verified');
                if (verifiedEl) {
                    verifiedEl.style.display = 'block';
                }
            }
        })
        .catch(error => {
            console.error('Error checking verification status:', error);
        });
    });
    */

    // Check email verification status
    ['email', 'email_address'].forEach(fieldType => {
        const currentEmail = document.getElementById(fieldType)?.value || '';
        fetch('/cif/check_email_verification_status', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
            },
            body: new URLSearchParams({
                'field_type': fieldType,
                'token': token,
                'current_email': currentEmail
            })
        })
        .then(response => response.json())
        .then(data => {
            // Update verification state for submit validation
            if (window.verificationStates) {
                window.verificationStates[fieldType] = data.verified || false;
            }
            if (data.success && data.verified) {
                // Hide verify button and OTP section
                const verifyBtn = document.getElementById('btn_verify_' + fieldType);
                if (verifyBtn) {
                    verifyBtn.style.display = 'none';
                }
                const otpSectionEl = document.getElementById(fieldType + '_otp_section');
                if (otpSectionEl) {
                    otpSectionEl.style.display = 'none';
                }
                // Show verified status
                const verifiedEl = document.getElementById(fieldType + '_verified');
                if (verifiedEl) {
                    verifiedEl.style.display = 'block';
                }
            }
        })
        .catch(error => {
            console.error('Error checking email verification status:', error);
        });
    });
}

// Reset verification when phone number changes
document.addEventListener('DOMContentLoaded', function() {
